/* Token Radar — dark radar-room palette: deep navy, amber signal, teal growth. */
:root {
  --bg: #0b1220;
  --panel: #111a2e;
  --panel-2: #16223c;
  --line: #24344f;
  --ink: #e8eef7;
  --muted: #9db0c9;
  --amber: #f5b942;
  --amber-ink: #1a1305;
  --teal: #3ecf9e;
  --red: #f27d7d;
  --blue: #6ea8fe;
  --radius: 10px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.55 "Segoe UI", system-ui, -apple-system, Roboto, sans-serif;
}
.top { background: linear-gradient(180deg, #0e1830, var(--bg)); border-bottom: 1px solid var(--line); }
.top-inner {
  max-width: 1180px; margin: 0 auto; padding: 28px 20px 8px;
  display: grid; grid-template-columns: 1fr 300px; gap: 28px; align-items: start;
}
.eyebrow { margin: 0 0 8px; color: var(--amber); font-size: 12px; letter-spacing: .14em; font-weight: 700; }
h1 { margin: 0 0 10px; font-size: 30px; line-height: 1.2; letter-spacing: -.01em; }
.lede { margin: 0; color: var(--muted); max-width: 62ch; }
.stats {
  margin: 4px 0 0; padding: 14px 16px; background: var(--panel); border: 1px solid var(--line);
  border-radius: var(--radius); display: grid; grid-template-columns: 1fr 1fr; gap: 10px 14px;
}
.stats dt { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .06em; }
.stats dd { margin: 2px 0 0; font-size: 19px; font-weight: 700; font-variant-numeric: tabular-nums; }
.stats dd small { font-size: 12px; color: var(--muted); font-weight: 400; }
.tabs { max-width: 1180px; margin: 0 auto; padding: 14px 20px 0; display: flex; gap: 8px; }
.tab {
  background: none; border: 1px solid var(--line); border-bottom: none; color: var(--muted);
  padding: 9px 16px; border-radius: 8px 8px 0 0; font: inherit; cursor: pointer;
}
.tab.active { background: var(--panel); color: var(--ink); border-color: var(--line); font-weight: 700; }
.tab:hover { color: var(--ink); }
main { max-width: 1180px; margin: 0 auto; padding: 18px 20px 30px; }
.view h2 { font-size: 22px; margin: 6px 0 8px; }
.view p { color: var(--muted); max-width: 78ch; }
.controls {
  display: flex; flex-wrap: wrap; gap: 12px 18px; align-items: end;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 12px 14px; margin-bottom: 10px;
}
.controls label { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
.controls input[type="search"], .controls select {
  display: block; margin-top: 4px; background: var(--bg); color: var(--ink);
  border: 1px solid var(--line); border-radius: 6px; padding: 7px 9px; font: inherit; font-size: 14px;
  text-transform: none; letter-spacing: 0;
}
.controls input[type="search"] { width: 230px; }
.controls .check { display: flex; align-items: center; gap: 6px; padding-bottom: 8px; text-transform: none; letter-spacing: 0; font-size: 14px; color: var(--ink); }
.count { margin: 4px 2px 10px; color: var(--muted); font-size: 13px; }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); }
table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
th, td { padding: 9px 12px; text-align: left; border-bottom: 1px solid var(--line); white-space: nowrap; }
th { font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); background: var(--panel-2); }
th button { all: unset; cursor: pointer; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; }
th button:hover { color: var(--amber); }
th.num, td.num { text-align: right; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #182747; }
tbody tr.selected { background: #1d2f52; box-shadow: inset 3px 0 0 var(--amber); }
td.name { font-weight: 700; white-space: normal; min-width: 170px; }
td.name small { display: block; color: var(--muted); font-weight: 400; font-size: 12px; }
.rank { color: var(--amber); font-weight: 700; }
.pos { color: var(--teal); } .neg { color: var(--red); }
.badge {
  display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: .05em;
  padding: 2px 7px; border-radius: 20px; margin-left: 6px; vertical-align: 1px;
}
.badge.watch { background: var(--amber); color: var(--amber-ink); }
.badge.early { background: #2b3f66; color: var(--blue); }
.hint { font-size: 13px; }
.detail {
  margin-top: 18px; background: var(--panel); border: 1px solid var(--amber);
  border-radius: var(--radius); padding: 20px 22px;
}
.detail h2 { margin: 0 0 4px; font-size: 24px; }
.detail .sub { color: var(--muted); margin: 0 0 14px; }
.detail h3 { font-size: 14px; text-transform: uppercase; letter-spacing: .07em; color: var(--amber); margin: 20px 0 8px; }
.detail p { color: var(--ink); }
.factors { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; margin: 10px 0; }
.factor { background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; }
.factor .k { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.factor .v { font-size: 20px; font-weight: 700; margin-top: 2px; }
.factor .bar { height: 6px; background: var(--bg); border-radius: 3px; margin-top: 8px; overflow: hidden; }
.factor .bar i { display: block; height: 100%; background: var(--amber); }
.factor .d { font-size: 12px; color: var(--muted); margin-top: 6px; }
.steps { margin: 0; padding-left: 22px; }
.steps li { margin: 8px 0; padding-left: 4px; }
.steps li::marker { color: var(--amber); font-weight: 700; }
.formula {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 16px 18px; overflow-x: auto; font-size: 14px; line-height: 1.7; color: var(--ink);
}
.mult-table { width: auto; }
.mult-table th, .mult-table td { white-space: normal; }
footer { max-width: 1180px; margin: 0 auto; padding: 0 20px 28px; color: var(--muted); font-size: 13px; }
footer p { max-width: 90ch; }
@media (max-width: 760px) {
  .top-inner { grid-template-columns: 1fr; }
  h1 { font-size: 24px; }
  .controls input[type="search"] { width: 100%; }
}
